#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int compare_i64(const void *a, const void *b) {
    long long ia = *(const long long*)a;
    long long ib = *(const long long*)b;
    return (ia > ib) - (ia < ib);
}

bool isPermutation(long long *lhs, size_t lhs_len, long long *rhs, size_t rhs_len) {
    if (lhs_len != rhs_len) {
        return false;
    }
    if (lhs_len == 0) {
        return true;
    }
    long long *sorted_lhs = malloc(lhs_len * sizeof(long long));
    long long *sorted_rhs = malloc(rhs_len * sizeof(long long));
    if (!sorted_lhs || !sorted_rhs) {
        free(sorted_lhs);
        free(sorted_rhs);
        return false;
    }
    for (size_t i = 0; i < lhs_len; i++) {
        sorted_lhs[i] = lhs[i];
        sorted_rhs[i] = rhs[i];
    }
    qsort(sorted_lhs, lhs_len, sizeof(long long), compare_i64);
    qsort(sorted_rhs, rhs_len, sizeof(long long), compare_i64);
    bool result = true;
    for (size_t i = 0; i < lhs_len; i++) {
        if (sorted_lhs[i] != sorted_rhs[i]) {
            result = false;
            break;
        }
    }
    free(sorted_lhs);
    free(sorted_rhs);
    return result;
}

int main() {
    long long test1_lhs[] = {1, 2, 3};
    long long test1_rhs[] = {3, 2, 1};
    printf("%d\n", isPermutation(test1_lhs, 3, test1_rhs, 3));

    long long test2_lhs[] = {5, 0, -1};
    long long test2_rhs[] = {0, 5, -1};
    printf("%d\n", isPermutation(test2_lhs, 3, test2_rhs, 3));

    long long test3_lhs[] = {7, 7, 7};
    long long test3_rhs[] = {7, 7, 8};
    printf("%d\n", isPermutation(test3_lhs, 3, test3_rhs, 3));

    long long test4_lhs[] = {};
    long long test4_rhs[] = {};
    printf("%d\n", isPermutation(test4_lhs, 0, test4_rhs, 0));

    long long test5_lhs[] = {100, -200, 300};
    long long test5_rhs[] = {100, -200};
    printf("%d\n", isPermutation(test5_lhs, 3, test5_rhs, 2));

    return 0;
}

