import java.util.Arrays;

public class Solution {
    public static boolean isPermutation(int[] lhs, int[] rhs) {
        if (lhs.length != rhs.length) {
            return false;
        }
        int[] sortedLhs = lhs.clone();
        int[] sortedRhs = rhs.clone();
        Arrays.sort(sortedLhs);
        Arrays.sort(sortedRhs);
        for (int i = 0; i < sortedLhs.length; i++) {
            if (sortedLhs[i] != sortedRhs[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Test 1: identical arrays
        int[] a1 = {1, 2, 3, 4, 5};
        int[] b1 = {1, 2, 3, 4, 5};
        System.out.println(isPermutation(a1, b1));

        // Test 2: permutation
        int[] a2 = {5, 3, 1, 4, 2};
        int[] b2 = {1, 2, 3, 4, 5};
        System.out.println(isPermutation(a2, b2));

        // Test 3: different lengths
        int[] a3 = {1, 2, 3};
        int[] b3 = {1, 2, 3, 4};
        System.out.println(isPermutation(a3, b3));

        // Test 4: empty arrays
        int[] a4 = {};
        int[] b4 = {};
        System.out.println(isPermutation(a4, b4));

        // Test 5: same elements, different counts
        int[] a5 = {1, 2, 2, 3};
        int[] b5 = {1, 2, 3, 3};
        System.out.println(isPermutation(a5, b5));
    }
}
